lay:inline-grid;place-items:center;background:#f8fafc;color:#94a3b8;font-size:7px}.is-broken{display:none}thead{display:table-header-group}a[href]:after{content:""}@media print{.no-print{display:none!important}.report-header{position:static}.catalog-print-table th{-webkit-print-color-adjust:exact;print-color-adjust:exact}.catalog-product-row{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
