@foreach($products as $row)<tbody class="catalog-product-group"><tr class="catalog-product-row"><td>{{ $loop->iteration }}</td><td><img class="catalog-print-image" src="{{ $row['image_url'] }}" alt="{{ $row['name'] }}" loading="eager" onerror="this.classList.add('is-broken');this.insertAdjacentHTML('afterend','<span class=&quot;placeholder&quot;>ARIA</span>')"></td><td class="product-name">{{ $row['name'] }}</td><td><span class="price">{{ $row['price_label'] }}</span></td></tr>@foreach($row['variants'] as $variant)<tr class="catalog-variant-row"><td></td><td></td><td class="variant-name">↳ {{ $variant['name'] }}</td><td><span class="price">{{ $variant['price_label'] }}</span></td></tr>@endforeach</tbody>@endforeach
</table></div><script>
const button=document.getElementById('printButton');const waitForImages=()=>Promise.all([...document.images].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.addEventListener('load',resolve,{once:true});img.addEventListener('error',resolve,{once:true});})));async function prepare(){if(document.fonts?.ready)await document.fonts.ready;await waitForImages();button.disabled=false;button.textContent='چاپ محصولات'}button.addEventListener('click',async()=>{button.disabled=true;button.textContent='آماده‌سازی...';await prepare();window.print();button.disabled=false;button.textContent='چاپ محصولات'});prepare();
</script></body></html>
